use std::sync::{Arc, RwLock};

let current = RwLock::new(Arc::new(Frame::default()));

let mut next = Frame::new();
render(&mut next);
let old = std::mem::replace(&mut *current.write().unwrap(), Arc::new(next));
drop(old);                                   // freed once readers are done
let frame = Arc::clone(&*current.read().unwrap());
